function parsePageSize(raw) {
  if (raw === null) return 20;
  if (typeof raw !== 'string' || !/^\d{1,3}$/.test(raw)) {
    throw new RangeError('pageSize must be an integer from 1 to 100');
  }
  const value = Number(raw);
  if (value < 1 || value > 100) throw new RangeError('pageSize out of range');
