async function inTransaction(pool, work) {
  const client = await pool.connect();
  let discard = false;
  try {
    await client.query('BEGIN');
    const value = await work(client);
    await client.query('COMMIT');
    return value;
  } catch (error) {
    try { await client.query('ROLLBACK'); }
    catch { discard = true; }
    throw error;
  } finally {
    client.release(discard);
  }
}
const statements = [];
const client = { query: async (sql) => statements.push(sql), release: () => statements.push('released') };
await inTransaction({ connect: async () => client }, (session) =>
  session.query('UPDATE orders SET status = $1 WHERE id = $2', ['ready', 42]),
);
console.log(statements);

