import { createServer } from 'node:http';

const server = createServer((_req, res) => res.end('ok'));
server.listen(3000, '127.0.0.1');
process.once('SIGTERM', () => {
  const limit = setTimeout(() => server.closeAllConnections(), 5_000);
  limit.unref();
  server.close((error) => {
    clearTimeout(limit);
    if (error) process.exitCode = 1;
  });
});

function loadConfig(env) {
  const portText = env.PORT ?? '3000';
  if (!/^\d{1,5}$/.test(portText) || Number(portText) < 1 || Number(portText) > 65535) {
    throw new Error('PORT must be an integer from 1 to 65535');
  }
  const featureText = env.FEATURE_REPORTS ?? 'false';
  if (!['true', 'false'].includes(featureText)) throw new Error('FEATURE_REPORTS must be true or false');
  return { port: Number(portText), reports: featureText === 'true' };
}
console.log(loadConfig({ PORT: '4001', FEATURE_REPORTS: 'false' }));

